25	package jenkins.widgets;
26	
27	import hudson.model.AbstractBuild;
28	import hudson.model.BallColor;
29	import hudson.model.Node;
30	import hudson.model.Run;
31	import jenkins.console.ConsoleUrlProvider;
32	import jenkins.model.Jenkins;
