37	@Restricted(DoNotUse.class) // only for buildTimeTrend.jelly
38	public class BuildTimeTrend extends RunListProgressiveRendering {
39	
40	    @Override protected void calculate(Run<?, ?> build, JSONObject element) {
41	        BallColor iconColor = build.getIconColor();
42	        element.put("iconName", iconColor.getIconName());
43	        element.put("iconColorOrdinal", iconColor.ordinal());
44	        element.put("iconColorDescription", iconColor.getDescription());
45	        element.put("number", build.getNumber());
46	        element.put("displayName", build.getDisplayName());
47	        element.put("duration", build.getDuration());
48	        element.put("durationString", build.getDurationString());
49	        element.put("consoleUrl", ConsoleUrlProvider.getRedirectUrl(build));
50	        if (build instanceof AbstractBuild) {
51	            AbstractBuild<?, ?> b = (AbstractBuild) build;
52	            Node n = b.getBuiltOn();
53	            if (n == null) {
54	                String ns = b.getBuiltOnStr();
55	                if (ns != null && !ns.isEmpty()) {
56	                    element.put("builtOnStr", ns);
57	                }
58	            } else if (n != Jenkins.get()) {
59	                element.put("builtOn", n.getNodeName());
60	                element.put("builtOnStr", n.getDisplayName());
61	            } else {
62	                element.put("builtOnStr", hudson.model.Messages.Hudson_Computer_DisplayName());
63	            }
64	        }
65	    }
66	
67	}
